/**
 * PageWand Safe MV3 Markdown Parser (marked.js compatible)
 */
(function (global) {
  function escapeMdHtml(str) {
    if (!str) return '';
    return str
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function sanitizeCspHtml(rawText) {
    if (!rawText) return '';
    return rawText
      .replace(/\s*on[a-z]+\s*=\s*["'][^"']*["']/gi, '')
      .replace(/\s*on[a-z]+\s*=\s*[^"'\s>]+/gi, '')
      .replace(/href\s*=\s*["']\s*javascript:[^"']*["']/gi, 'href="#"');
  }

  function parseMarkdown(md) {
    if (!md) return '';
    
    // Normalize newlines & sanitize inline event handlers
    let text = sanitizeCspHtml(md.replace(/\r\n|\r/g, '\n'));

    // Code blocks parser
    const codeBlocks = [];
    text = text.replace(/```(\w*)\n([\s\S]*?)```/g, function (match, lang, code) {
      const id = '___CODE_BLOCK_' + codeBlocks.length + '___';
      codeBlocks.push(`<pre><code class="language-${lang || 'text'}">${escapeMdHtml(code.trim())}</code></pre>`);
      return id;
    });

    // Inline code
    const inlineCodes = [];
    text = text.replace(/`([^`]+)`/g, function (match, code) {
      const id = '___INLINE_CODE_' + inlineCodes.length + '___';
      inlineCodes.push(`<code>${escapeMdHtml(code)}</code>`);
      return id;
    });

    // Headers
    text = text.replace(/^######\s+(.*)$/gm, '<h6>$1</h6>');
    text = text.replace(/^#####\s+(.*)$/gm, '<h5>$1</h5>');
    text = text.replace(/^####\s+(.*)$/gm, '<h4>$1</h4>');
    text = text.replace(/^###\s+(.*)$/gm, '<h3>$1</h3>');
    text = text.replace(/^##\s+(.*)$/gm, '<h2>$1</h2>');
    text = text.replace(/^#\s+(.*)$/gm, '<h1>$1</h1>');

    // Blockquotes
    text = text.replace(/^>\s+(.*)$/gm, '<blockquote>$1</blockquote>');

    // Horizontal Rules
    text = text.replace(/^---$/gm, '<hr>');

    // Bold and Italic
    text = text.replace(/\*\*\*(.*?)\*\*\*/g, '<strong><em>$1</em></strong>');
    text = text.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
    text = text.replace(/\*(.*?)\*/g, '<em>$1</em>');

    // Safe Links
    text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, function (m, label, href) {
      const safeHref = href.trim().toLowerCase().startsWith('javascript:') ? '#' : escapeMdHtml(href);
      return `<a href="${safeHref}" target="_blank" rel="noopener noreferrer">${label}</a>`;
    });

    // Unordered Lists
    text = text.replace(/^\s*[-*+]\s+(.*)$/gm, '<li>$1</li>');
    text = text.replace(/(<li>.*<\/li>\n?)+/g, '<ul>$&</ul>');

    // GFM tables (| a | b |\n| --- | --- |)
    text = text.replace(/(^|\n)(\|[^\n]+\|(?:\n\|[^\n]+\|)+)/g, function (_m, lead, block) {
      const rows = block.trim().split('\n');
      if (rows.length < 2) return _m;
      function splitRow(line) {
        var s = line.trim();
        if (s.charAt(0) === '|') s = s.slice(1);
        if (s.charAt(s.length - 1) === '|') s = s.slice(0, -1);
        return s.split('|').map(function (c) { return c.trim(); });
      }
      var header = splitRow(rows[0]);
      var sep = splitRow(rows[1]);
      if (!sep.length || !sep.every(function (c) { return /^:?-{1,}:?$/.test(c.replace(/\s/g, '')); })) {
        return _m;
      }
      var aligns = sep.map(function (c) {
        var left = c.charAt(0) === ':';
        var right = c.charAt(c.length - 1) === ':';
        if (left && right) return 'center';
        if (right) return 'right';
        return 'left';
      });
      var th = header.map(function (h, i) {
        return '<th style="text-align:' + (aligns[i] || 'left') + '">' + h + '</th>';
      }).join('');
      var body = rows.slice(2).map(function (line) {
        var cells = splitRow(line);
        return '<tr>' + header.map(function (_h, i) {
          return '<td style="text-align:' + (aligns[i] || 'left') + '">' + (cells[i] || '') + '</td>';
        }).join('') + '</tr>';
      }).join('');
      return lead + '<div class="md-table-wrap"><table class="md-table"><thead><tr>' + th + '</tr></thead><tbody>' + body + '</tbody></table></div>';
    });

    // Paragraphs for remaining plain lines
    const lines = text.split('\n');
    const processedLines = lines.map(function (line) {
      const trimmed = line.trim();
      if (!trimmed) return '';
      if (/^<(h[1-6]|ul|ol|li|blockquote|pre|hr|div|table)/.test(trimmed)) {
        return line;
      }
      if (trimmed.startsWith('___CODE_BLOCK_') || trimmed.startsWith('___INLINE_CODE_')) {
        return line;
      }
      return '<p>' + line + '</p>';
    });

    text = processedLines.join('\n');

    // Restore Code blocks and Inline codes
    inlineCodes.forEach(function (html, i) {
      text = text.replace('___INLINE_CODE_' + i + '___', html);
    });
    codeBlocks.forEach(function (html, i) {
      text = text.replace('___CODE_BLOCK_' + i + '___', html);
    });

    return text;
  }

  const markedObj = {
    parse: parseMarkdown,
    marked: parseMarkdown
  };

  global.marked = markedObj;
})(typeof globalThis !== 'undefined' ? globalThis : self);
